import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin } from './helpers';

test.describe(`team member: add comments and link PRs to a task`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member adds a comment or PR link to a task, it appears in that task's history for everyone`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    await pageA.getByTestId('field-name').fill('Backend');
    await pageA.getByTestId('action-create_category').click();
    await expect(pageA.locator('[data-testid^="item-category-"]').filter({ hasText: 'Backend' })).toBeVisible({ timeout: 10_000 });

    await pageA.getByTestId('field-title').fill('Fix login bug');
    // The board is shared across every spec file in the suite, so the form's
    // default category (categories[0]) is not guaranteed to be the one just
    // created here — select it explicitly.
    await pageA.getByTestId('field-category_id').selectOption({ label: 'Backend' });
    await pageA.getByTestId('field-assignee').fill('alice');
    await pageA.getByTestId('action-create_task').click();
    const taskCardA = pageA.locator('[data-testid^="item-task-"]').filter({ hasText: 'Fix login bug' });
    await expect(taskCardA).toBeVisible({ timeout: 10_000 });
    await taskCardA.click();

    await pageA.getByTestId('field-body').fill('Fixed in PR');
    await pageA.getByTestId('field-pr_link').fill('https://github.com/org/repo/pull/42');
    await pageA.getByTestId('action-add_comment').click();
    await expect(pageA.getByText('Fixed in PR')).toBeVisible({ timeout: 10_000 });

    // B opens the same task and sees the comment + PR link in its history.
    const taskCardB = pageB.locator('[data-testid^="item-task-"]').filter({ hasText: 'Fix login bug' });
    await expect(taskCardB).toBeVisible({ timeout: 10_000 });
    await taskCardB.click();
    await expect(pageB.getByText('Fixed in PR')).toBeVisible({ timeout: 10_000 });
    await expect(pageB.getByText('https://github.com/org/repo/pull/42')).toBeVisible();

    await ctxA.close();
    await ctxB.close();
  });

  test(`a member can only edit or delete comments they authored`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    await pageA.getByTestId('field-name').fill('Backend');
    await pageA.getByTestId('action-create_category').click();
    await expect(pageA.locator('[data-testid^="item-category-"]').filter({ hasText: 'Backend' })).toBeVisible({ timeout: 10_000 });

    await pageA.getByTestId('field-title').fill('Fix login bug');
    // The board is shared across every spec file in the suite, so the form's
    // default category (categories[0]) is not guaranteed to be the one just
    // created here — select it explicitly.
    await pageA.getByTestId('field-category_id').selectOption({ label: 'Backend' });
    await pageA.getByTestId('field-assignee').fill('alice');
    await pageA.getByTestId('action-create_task').click();
    const taskCardA = pageA.locator('[data-testid^="item-task-"]').filter({ hasText: 'Fix login bug' });
    await expect(taskCardA).toBeVisible({ timeout: 10_000 });
    await taskCardA.click();

    await pageA.getByTestId('field-body').fill('Authored by A');
    await pageA.getByTestId('action-add_comment').click();
    const commentRowA = pageA.locator('[data-testid^="item-comment-"]').filter({ hasText: 'Authored by A' });
    await expect(commentRowA).toBeVisible({ timeout: 10_000 });
    // The author sees edit/delete controls on their own comment.
    await expect(commentRowA.getByTestId('action-edit_comment')).toBeVisible();
    await expect(commentRowA.getByTestId('action-delete_comment')).toBeVisible();

    // B opens the same task and sees the comment, but has no edit/delete
    // controls for it since B did not author it.
    const taskCardB = pageB.locator('[data-testid^="item-task-"]').filter({ hasText: 'Fix login bug' });
    await expect(taskCardB).toBeVisible({ timeout: 10_000 });
    await taskCardB.click();
    const commentRowB = pageB.locator('[data-testid^="item-comment-"]').filter({ hasText: 'Authored by A' });
    await expect(commentRowB).toBeVisible({ timeout: 10_000 });
    await expect(commentRowB.getByTestId('action-edit_comment')).toHaveCount(0);
    await expect(commentRowB.getByTestId('action-delete_comment')).toHaveCount(0);

    await ctxA.close();
    await ctxB.close();
  });
});
